def test_top_customers_ranks_filters_and_limits(shop):
    shop.customers.handle_register({"customer_id": "c0", "name": "Zed", "email": "z@example.com"})
    shop.customers.handle_register({"customer_id": "c3", "name": "Idle", "email": "i@example.com"})
    order(shop, "c1", ("BOOK", 1))
    order(shop, "c0", ("BOOK", 1))
    cancelled = order(shop, "c3", ("LAMP", 1)).body["order_id"]
    shop.orders.handle_cancel(cancelled)
    order(shop, "c2", ("LAMP", 1))
    ltv = {c: shop.insights.handle_lifetime_value(c).body["lifetime_value_cents"]
           for c in ("c0", "c1", "c2")}
    assert ltv["c0"] == ltv["c1"] > 0
    resp = shop.insights.handle_top_customers(10)
    assert resp.status == 200
    ranked = sorted(ltv, key=lambda c: (-ltv[c], c))
    assert [e["customer_id"] for e in resp.body["customers"]] == ranked
    assert "c3" not in [e["customer_id"] for e in resp.body["customers"]]
    assert resp.body["customers"][0]["name"] in {"Ada", "Grace", "Zed"}
    limited = shop.insights.handle_top_customers(2)
    assert [e["customer_id"] for e in limited.body["customers"]] == ranked[:2]


